    const f32 l = next_sample(r);
    const f32 g = gain_ * fade_ * 0.7;
    converted::at(out, 2 * i) += l * g;
    converted::at(out, 2 * i + 1) += r * g;
    peak = std::fmax(peak, std::fabs(l * g));
